mapper.select:
SELECT

FROM doc_annotation WHERE doc_id = #{docId}
ORDER BY anchor_index ASC, created_at ASC

mapper.update:
UPDATE doc_annotation
SET anchor_hash = #{anchorHash}, anchor_index = #{anchorIndex}, status = #{status}, block_snippet = #{blockSnippet}
WHERE id = #{id}

mapper.select:
SELECT COUNT(*) FROM doc_annotation
WHERE doc_id != #{excludeDocId}
  AND (block_snippet LIKE #{pattern} OR content_md LIKE #{pattern})
